      "keystrokes": "cat > main.cpp <<'CPP'\n#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n;\n    long long hx, hy, dx, dy;\n    // Process multiple test cases until termination line\n    while (cin >> n >> hx >> hy >> dx >> dy) {\n        if (n == 0 && hx == 0 && hy == 0 && dx == 0 && dy == 0) break;\n        vector<long long> cx(n), cy(n);\n        for (int i = 0; i < n; ++i) {\n            cin >> cx[i] >> cy[i];\n        }\n\n        vector<double> distD(n), distH(n);\n        vector<vector<double>> dist(n, vector<double>(n, 0.0));\n        for (int i = 0; i < n; ++i) {\n            distD[i] = hypot((double)cx[i] - dx, (double)cy[i] - dy);\n            distH[i] = hypot((double)cx[i] - hx, (double)cy[i] - hy);\n        }\n        for (int i = 0; i < n; ++i) {\n            for (int j = 0; j < n; ++j) {\n                dist[i][j] = hypot((double)cx[i] - cx[j], (double)cy[i] - cy[j]);\n            }\n        }\n\n        int M = 1 << n;\n        const double EPS = 1e-12;\n        const float INF = 1e30f; // large sentinel for float DP\n        // dp[mask * n + last] = minimum time to reach 'mask' ending at crystal 'last'\n        vector<float> dp((size_t)M * n, INF);\n        auto idx = [n](int mask, int last) -> size_t { return (size_t)mask * n + last; };\n\n        // Initialize from the starting position H\n        for (int i = 0; i < n; ++i) {\n            if (distH[i] < distD[i] - EPS) {\n                dp[idx(1 << i, i)] = (float)distH[i];\n            }\n        }\n\n        for (int mask = 0; mask < M; ++mask) {\n            for (int last = 0; last < n; ++last) {\n                float tFloat = dp[idx(mask, last)];\n                if (tFloat >= INF) continue;\n                double t = (double)tFloat;\n                int rem = (~mask) & (M - 1);\n                while (rem) {\n                    int lsb = rem & -rem;\n                    int j = __builtin_ctz(lsb);\n                    double nt = t + dist[last][j];\n                    if (nt < distD[j] - EPS) {\n                        int nmask = mask | lsb;\n                        size_t id = idx(nmask, j);\n                        if ((float)nt < dp[id]) dp[id] = (float)nt;\n                    }\n                    rem -= lsb;\n                }\n            }\n        }\n\n        bool ok = false;\n        int full = M - 1;\n        for (int i = 0; i < n; ++i) {\n            if (dp[idx(full, i)] < INF) { ok = true; break; }\n        }\n        cout << (ok ? \"YES\" : \"NO\") << \"\\n\";\n    }\n    return 0;\n}\nCPP\n",
